-- Name: parameter_definitions; Type: TABLE; Schema: platform; Owner: omitted
--

CREATE TABLE platform.parameter_definitions (
    tenant_id character varying(256) NOT NULL,
    tool character varying(64) NOT NULL,
    variable_name character varying(64) NOT NULL,
    value_type character varying(16) NOT NULL,
    description character varying(2000) NOT NULL,
    default_value jsonb NOT NULL,
    allow_project_override boolean NOT NULL,
    icon character varying(64) NOT NULL,
    revision integer NOT NULL,
    updated_at double precision NOT NULL,
    edited_time timestamp with time zone NOT NULL,
    etl_src_system text NOT NULL,
    etl_batch_id text NOT NULL,
    created_by text NOT NULL,
    edited_by text NOT NULL,
    created_time timestamp with time zone NOT NULL,
    scope character varying(16) DEFAULT 'platform'::character varying NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    category character varying(120) DEFAULT 'operational'::character varying NOT NULL,
    subcategory character varying(120),
    allowed_values jsonb,
    label character varying(256),
    section character varying(64),
    display_order integer,
    is_required boolean DEFAULT false NOT NULL,
    ownership character varying(32) DEFAULT 'runtime'::character varying NOT NULL,
    validation_rules jsonb,
    runtime_binding character varying(128),
    CONSTRAINT parameter_default_typed CHECK (platform.parameter_value_valid((value_type)::text, default_value)),
    CONSTRAINT parameter_definition_category_nonempty CHECK (((category)::text <> ''::text)),
    CONSTRAINT parameter_definition_scope_check CHECK (((scope)::text = ANY ((ARRAY['platform'::character varying, 'project'::character varying, 'platform_only'::character varying])::text[]))),
    CONSTRAINT parameter_definitions_revision_check CHECK ((revision > 0)),
    CONSTRAINT parameter_definitions_value_type_check CHECK (((value_type)::text = ANY ((ARRAY['string'::character varying, 'integer'::character varying, 'number'::character varying, 'boolean'::character varying, 'json'::character varying, 'secret_ref'::character varying])::text[]))),
    CONSTRAINT parameter_identifiers CHECK ((((tool)::text ~ '^[a-z][a-z0-9_]{0,63}$'::text) AND ((variable_name)::text ~ '^[a-z][a-z0-9_]{0,63}$'::text))),
    CONSTRAINT parameter_secret_reference CHECK ((((variable_name)::text !~ '(^|_)(password|token|secret|api_key|credential)(_|$)'::text) OR ((value_type)::text = 'secret_ref'::text)))
);


